SHOW GIT REPOSITORIES;

SHOW GIT REPOSITORIES LIKE 'snow%' IN SCHEMA my_db.my_schema;

SHOW GIT BRANCHES IN snowflake_extensions;

SHOW GIT BRANCHES LIKE 'feat%' IN GIT REPOSITORY my_db.my_schema.my_repo;

SHOW GIT TAGS IN my_repo;

SHOW GIT TAGS LIKE 'v1%' IN GIT REPOSITORY my_repo;

DESCRIBE GIT REPOSITORY my_repo;

DESC GIT REPOSITORY my_db.my_schema.my_repo;

DROP GIT REPOSITORY my_repo;

DROP GIT REPOSITORY IF EXISTS my_db.my_schema.my_repo;

GRANT READ ON GIT REPOSITORY my_repo TO ROLE my_role;

GRANT WRITE ON GIT REPOSITORY my_db.my_schema.my_repo TO ROLE my_role;

GRANT READ ON ALL GIT REPOSITORIES IN SCHEMA my_db.my_schema TO ROLE my_role;

GRANT READ ON FUTURE GIT REPOSITORIES IN SCHEMA my_db.my_schema TO ROLE my_role;

REVOKE READ ON GIT REPOSITORY my_repo FROM ROLE my_role;

REVOKE READ ON ALL GIT REPOSITORIES IN SCHEMA my_db.my_schema FROM ROLE my_role;

REVOKE READ ON FUTURE GIT REPOSITORIES IN SCHEMA my_db.my_schema FROM ROLE my_role;

GRANT CREATE GIT REPOSITORY ON SCHEMA my_db.my_schema TO ROLE my_role;
